-- MotorcycleSalesAPP SaaS foundation v1
-- Additive migration: keeps existing business records and places them in the Bayhas Motors tenant.
-- BACK UP THE DATABASE BEFORE RUNNING. Run after upgrade_v4.sql and upgrade_v4_4.sql.
BEGIN;

CREATE TABLE IF NOT EXISTS "Tenants" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(180) NOT NULL,
    "Slug" varchar(80) NOT NULL,
    "LegalName" varchar(180) NULL,
    "ContactEmail" varchar(180) NULL,
    "Phone" varchar(40) NULL,
    "PlanKey" varchar(40) NOT NULL DEFAULT 'Trial',
    "SubscriptionStatus" varchar(40) NOT NULL DEFAULT 'Trial',
    "TrialEndsAt" timestamptz NULL,
    "SubscriptionEndsAt" timestamptz NULL,
    "MaxUsers" integer NOT NULL DEFAULT 5,
    "MaxBranches" integer NOT NULL DEFAULT 1,
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Tenants_Slug" ON "Tenants" ("Slug");

INSERT INTO "Tenants" ("Name", "Slug", "PlanKey", "SubscriptionStatus", "TrialEndsAt", "MaxUsers", "MaxBranches")
VALUES ('Bayhas Motors', 'bayhas-motors', 'Legacy', 'Active', NULL, 50, 10)
ON CONFLICT ("Slug") DO NOTHING;

DO $$
DECLARE
    tenant_id integer;
    table_name text;
    fk_name text;
    idx_name text;
    tenant_tables text[] := ARRAY[
        'AppUsers', 'Motorcycles', 'Sales', 'Customers', 'StockMovements', 'Expenses',
        'Dealers', 'DealerStocks', 'StockTransfers', 'Accounts', 'JournalEntries',
        'JournalLines', 'Payments', 'WorkflowRecords', 'CatalogListings', 'AuditLogs'
    ];
BEGIN
    SELECT "Id" INTO tenant_id FROM "Tenants" WHERE "Slug" = 'bayhas-motors' LIMIT 1;

    FOREACH table_name IN ARRAY tenant_tables LOOP
        IF to_regclass(format('%I', table_name)) IS NOT NULL THEN
            EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS "TenantId" integer', table_name);
            EXECUTE format('UPDATE %I SET "TenantId" = $1 WHERE "TenantId" IS NULL', table_name) USING tenant_id;
            EXECUTE format('ALTER TABLE %I ALTER COLUMN "TenantId" SET NOT NULL', table_name);

            fk_name := 'FK_' || table_name || '_Tenants_TenantId';
            IF NOT EXISTS (
                SELECT 1 FROM pg_constraint
                WHERE conname = fk_name AND conrelid = to_regclass(format('%I', table_name))
            ) THEN
                EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I FOREIGN KEY ("TenantId") REFERENCES "Tenants"("Id") ON DELETE RESTRICT', table_name, fk_name);
            END IF;

            idx_name := 'IX_' || table_name || '_TenantId';
            EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I ("TenantId")', idx_name, table_name);
        END IF;
    END LOOP;
END $$;

-- Usernames, dealer codes and account codes are unique inside a tenant, not globally.
DROP INDEX IF EXISTS "IX_AppUsers_Username";
CREATE UNIQUE INDEX IF NOT EXISTS "IX_AppUsers_TenantId_Username" ON "AppUsers" ("TenantId", "Username");
DROP INDEX IF EXISTS "IX_Dealers_Code";
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Dealers_TenantId_Code" ON "Dealers" ("TenantId", "Code");
DROP INDEX IF EXISTS "IX_Accounts_Code";
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Accounts_TenantId_Code" ON "Accounts" ("TenantId", "Code");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DealerStocks_TenantId_DealerId_MotorcycleId" ON "DealerStocks" ("TenantId", "DealerId", "MotorcycleId");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_CatalogListings_TenantId_MotorcycleId" ON "CatalogListings" ("TenantId", "MotorcycleId");
CREATE INDEX IF NOT EXISTS "IX_WorkflowRecords_TenantId_Module_DueAt" ON "WorkflowRecords" ("TenantId", "Module", "DueAt");
CREATE INDEX IF NOT EXISTS "IX_AuditLogs_TenantId_CreatedAt" ON "AuditLogs" ("TenantId", "CreatedAt" DESC);


-- Composite unique keys and foreign keys prevent records from referencing another tenant's rows.
DO $$
DECLARE
    key_def record;
BEGIN
    FOR key_def IN SELECT * FROM (VALUES
        ('Motorcycles','AK_Motorcycles_TenantId_Id'),
        ('Customers','AK_Customers_TenantId_Id'),
        ('Dealers','AK_Dealers_TenantId_Id'),
        ('Sales','AK_Sales_TenantId_Id'),
        ('JournalEntries','AK_JournalEntries_TenantId_Id'),
        ('Accounts','AK_Accounts_TenantId_Id')
    ) AS k(table_name, constraint_name)
    LOOP
        IF NOT EXISTS (
            SELECT 1 FROM pg_constraint
            WHERE conname = key_def.constraint_name
              AND conrelid = to_regclass(format('%I', key_def.table_name))
        ) THEN
            EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I UNIQUE ("TenantId", "Id")', key_def.table_name, key_def.constraint_name);
        END IF;
    END LOOP;
END $$;

DO $$
DECLARE
    relation record;
BEGIN
    FOR relation IN SELECT * FROM (VALUES
        ('Sales','FK_Sales_Tenant_Motorcycle','FOREIGN KEY ("TenantId", "MotorcycleId") REFERENCES "Motorcycles"("TenantId", "Id")'),
        ('Sales','FK_Sales_Tenant_Customer','FOREIGN KEY ("TenantId", "CustomerId") REFERENCES "Customers"("TenantId", "Id")'),
        ('Sales','FK_Sales_Tenant_Dealer','FOREIGN KEY ("TenantId", "DealerId") REFERENCES "Dealers"("TenantId", "Id")'),
        ('StockMovements','FK_StockMovements_Tenant_Motorcycle','FOREIGN KEY ("TenantId", "MotorcycleId") REFERENCES "Motorcycles"("TenantId", "Id")'),
        ('DealerStocks','FK_DealerStocks_Tenant_Dealer','FOREIGN KEY ("TenantId", "DealerId") REFERENCES "Dealers"("TenantId", "Id")'),
        ('DealerStocks','FK_DealerStocks_Tenant_Motorcycle','FOREIGN KEY ("TenantId", "MotorcycleId") REFERENCES "Motorcycles"("TenantId", "Id")'),
        ('StockTransfers','FK_StockTransfers_Tenant_Motorcycle','FOREIGN KEY ("TenantId", "MotorcycleId") REFERENCES "Motorcycles"("TenantId", "Id")'),
        ('StockTransfers','FK_StockTransfers_Tenant_FromDealer','FOREIGN KEY ("TenantId", "FromDealerId") REFERENCES "Dealers"("TenantId", "Id")'),
        ('StockTransfers','FK_StockTransfers_Tenant_ToDealer','FOREIGN KEY ("TenantId", "ToDealerId") REFERENCES "Dealers"("TenantId", "Id")'),
        ('JournalLines','FK_JournalLines_Tenant_JournalEntry','FOREIGN KEY ("TenantId", "JournalEntryId") REFERENCES "JournalEntries"("TenantId", "Id") ON DELETE CASCADE'),
        ('JournalLines','FK_JournalLines_Tenant_Account','FOREIGN KEY ("TenantId", "AccountId") REFERENCES "Accounts"("TenantId", "Id")'),
        ('AppUsers','FK_AppUsers_Tenant_Dealer','FOREIGN KEY ("TenantId", "DealerId") REFERENCES "Dealers"("TenantId", "Id")'),
        ('Payments','FK_Payments_Tenant_Sale','FOREIGN KEY ("TenantId", "SaleId") REFERENCES "Sales"("TenantId", "Id")'),
        ('Payments','FK_Payments_Tenant_Dealer','FOREIGN KEY ("TenantId", "DealerId") REFERENCES "Dealers"("TenantId", "Id")'),
        ('Payments','FK_Payments_Tenant_Customer','FOREIGN KEY ("TenantId", "CustomerId") REFERENCES "Customers"("TenantId", "Id")'),
        ('WorkflowRecords','FK_WorkflowRecords_Tenant_Customer','FOREIGN KEY ("TenantId", "CustomerId") REFERENCES "Customers"("TenantId", "Id")'),
        ('WorkflowRecords','FK_WorkflowRecords_Tenant_Motorcycle','FOREIGN KEY ("TenantId", "MotorcycleId") REFERENCES "Motorcycles"("TenantId", "Id")'),
        ('WorkflowRecords','FK_WorkflowRecords_Tenant_Dealer','FOREIGN KEY ("TenantId", "DealerId") REFERENCES "Dealers"("TenantId", "Id")'),
        ('CatalogListings','FK_CatalogListings_Tenant_Motorcycle','FOREIGN KEY ("TenantId", "MotorcycleId") REFERENCES "Motorcycles"("TenantId", "Id")')
    ) AS r(table_name, constraint_name, constraint_sql)
    LOOP
        IF to_regclass(format('%I', relation.table_name)) IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM pg_constraint
            WHERE conname = relation.constraint_name
              AND conrelid = to_regclass(format('%I', relation.table_name))
        ) THEN
            EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I %s NOT VALID', relation.table_name, relation.constraint_name, relation.constraint_sql);
        END IF;
    END LOOP;
END $$;

COMMIT;
